function report(items, now) {
  const rows = items.flatMap(({ json }) => Array.isArray(json) ? json : [json]);
  const pages = rows.filter(row => row?.recordType === 'page' && row.ok === true);
  const important = new Set(['http-error', 'redirect', 'noindex', 'noindex-in-sitemap', 'canonical-differs']);
  const flaggedPages = pages.flatMap(row => {
    const ids = new Set((Array.isArray(row.findings) ? row.findings : [])
      .map(f => f?.id).filter(id => important.has(id)));
    // The final response can be 200 after a redirect, so keep its chain signal.
    if (Number.isInteger(row.redirectCount) && row.redirectCount > 0) ids.add('redirect');
    if (Number.isInteger(row.httpStatus) && row.httpStatus >= 400) ids.add('http-error');
    if (ids.has('noindex-in-sitemap')) ids.delete('noindex');
    if (!ids.size) return [];
    return [{ url: row.url, finalUrl: row.finalUrl ?? null, status: row.httpStatus ?? null,
      canonicalUrl: row.canonicalUrl ?? null, signals: [...ids].sort() }];
  });
  const errors = rows.filter(row => row?.ok === false)
    .map(row => ({ url: row.url ?? row.input ?? null, code: row.errorCode ?? null }));
  return {
    checkedAt: now,
    state: !pages.length ? 'no-pages-audited' : errors.length ? 'incomplete' :
      flaggedPages.length ? 'findings' : 'no-matching-findings-in-sample',
    pagesAudited: pages.length,
    flaggedPages,
    errors,
    note: 'A bounded sample, not a full-site audit or proof of Google indexing. Check Actor run details for limits and skipped URLs.',
  };
}

return [{ json: report($input.all(), new Date().toISOString()) }];
